C[3] = dict(
    match=[("charger", "you plug it in to give the laptop power"), ("password", "the secret word for your login"), ("frozen", "the screen stops and nothing moves"),
           ("printer", "it puts a document on paper"), ("cupboard", "you keep equipment in it"), ("update", "the new version of an app")],
    thread=("Lena's message to IT", [
        "Hi Priya! On my desk there (1) ___ a laptop and a keyboard, but there isn't a (2) ___.", "There (3) ___ two cables — I don't know what they are for.",
        "Is there a (4) ___ for the printer? I don't have one.", "Are there (5) ___ headphones in the cupboard?", "Also: my (6) ___ is frozen again! Thanks."],
        ["any", "are", "is", "mouse", "password", "screen"], ["is", "mouse", "are", "password", "any", "screen"]),
    form="*There is* + one thing: *There's a printer.* *There are* + more than one: *There are two screens.* Questions: *Is there …? Are there …?*",
    use="Say what exists and where. Use *some* in positive sentences: *There are some cables.* Use *any* in questions and negatives: *Is there any paper? There aren't any cups.*",
    watch="*There's* is not *it's*. *There's a printer* (it exists) — *It's a printer* (what it is). *Any* goes with plurals and uncountables: *any apps, any paper.*",
    practice=[("___ a printer in the office? (Is there / Are there)", "Is there"), ("There ___ some cables in the drawer.", "are"), ("There isn't ___ paper.", "any"),
              ("Are there ___ headphones?", "any"), ("There ___ a green light on the laptop.", "is"), ("There are ___ apps I need. (some / any)", "some")],
    gist=[("What is Lena's first problem?", "Her screen is frozen."), ("What does Priya tell her to do?", "Hold the power button for ten seconds.")],
    controlled=[("My screen ___ frozen. (is / are)", "is"), ("Can I ___ the chat app, please? (have / has)", "have"), ("___ there a second screen? (Is / Are)", "Is"),
                ("There ___ some in the cupboard. (is / are)", "are"), ("I don't have ___ passwords. (some / any)", "any"), ("Try ___: hold the button. (this / these)", "this")],
    roleA="It is your first day. Tell IT what there is on your desk and what there isn't. Ask for three things you need. One thing on your laptop doesn't work — say what.",
    roleB="You are IT. Listen, and tell Student A what to try: *Try this: …* Say where the things they need are: *There are some in the cupboard.* Ask: *Anything else?*",
    script=[("Tom", "Priya, the printer isn't working. There's a red light."), ("Priya", "OK. Is there any paper in it?"), ("Tom", "Er … no. There isn't any paper."),
            ("Priya", "There's some in the cupboard, on the left."), ("Tom", "Got it. … It's working now! Thanks."), ("Priya", "Anything else?"),
            ("Tom", "One more thing. Is there a new password for the Wi-Fi?"), ("Priya", "Yes. It's in your email.")],
    listen=[("What is wrong with the printer?", "It isn't working; there's a red light."), ("What is the real problem?", "There isn't any paper."),
            ("Where is the paper?", "In the cupboard, on the left."), ("What is Tom's second question?", "Is there a new Wi-Fi password?")],
    mini="Student A: your laptop has a problem — say what. Student B: give one thing to try. Then swap. One minute.",
    pron="*There's* sounds like *thairz*, one word. *Is there …?* — the voice goes up at the end. *It's working now!* — strong on *work*.",
    ref="**There is / there are; some / any.** *There is* (*there's*) with a singular or uncountable noun: *There's a laptop. There's some paper.* *There are* with a plural: *There are two screens.* Negative: *There isn't / There aren't.* Question: *Is there …? Are there …?* *Some* in positive sentences and offers; *any* in questions and negatives: *There are some cables. Are there any cups? There aren't any.*",
)

